    .reg .pred %p<16>;
    .reg .s32 %r<32>;
    .reg .s64 %rd<40>;
    .reg .f32 %f<40>;
    .reg .f64 %fd<45>;

    .shared .align 8 .f64 s_sum[1024];
    .shared .align 8 .f64 s_sumsq[1024];
    .shared .align 8 .f64 s_mean;
    .shared .align 8 .f64 s_invstd;

    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u64 %rd3, [weight_ptr];
    ld.param.u64 %rd4, [bias_ptr];
    ld.param.u32 %r1, [N];
    ld.param.f32 %f1, [eps];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %ctaid.x;

    // batch_offset = ctaid.x * N
    mul.lo.s32 %r5, %r4, %r1;
    mul.wide.s32 %rd5, %r5, 4;
    add.s64 %rd6, %rd1, %rd5;   // x_base
    add.s64 %rd7, %rd2, %rd5;   // out_base

    // ---- Pass 1: compute sum and sumsq ----
    mov.f64 %fd1, 0d0000000000000000;
    mov.f64 %fd2, 0d0000000000000000;
    mul.lo.s32 %r6, %r2, 4;
    mul.lo.s32 %r7, %r3, 4;

loop1:
    setp.ge.s32 %p1, %r6, %r1;
    @%p1 bra loop1_end;

    mul.wide.s32 %rd8, %r6, 4;
    add.s64 %rd9, %rd6, %rd8;
    ld.global.v4.f32 {%f2, %f3, %f4, %f5}, [%rd9];
    cvt.f64.f32 %fd3, %f2;
    cvt.f64.f32 %fd4, %f3;
    cvt.f64.f32 %fd5, %f4;
    cvt.f64.f32 %fd6, %f5;
    add.f64 %fd1, %fd1, %fd3;
    add.f64 %fd1, %fd1, %fd4;
    add.f64 %fd1, %fd1, %fd5;
    add.f64 %fd1, %fd1, %fd6;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;
    fma.rn.f64 %fd2, %fd4, %fd4, %fd2;
    fma.rn.f64 %fd2, %fd5, %fd5, %fd2;
    fma.rn.f64 %fd2, %fd6, %fd6, %fd2;
    add.s32 %r6, %r6, %r7;
