    mov.u64 %rd11, s_sumsq;
    mul.wide.s32 %rd12, %r2, 8;
    add.s64 %rd13, %rd10, %rd12;
    add.s64 %rd14, %rd11, %rd12;
    st.shared.f64 [%rd13], %fd1;
    st.shared.f64 [%rd14], %fd2;

    bar.sync 0;

