    @!%p9 bra red512_end;
    add.s32 %r20, %r2, 512;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
red512_end:
    bar.sync 0;
    setp.lt.s32 %p9, %r2, 256;
    @!%p9 bra red256_end;
    add.s32 %r20, %r2, 256;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
red256_end:
    bar.sync 0;
    setp.lt.s32 %p9, %r2, 128;
    @!%p9 bra red128_end;
    add.s32 %r20, %r2, 128;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
red128_end:
    bar.sync 0;

    setp.lt.s32 %p9, %r2, 64;
    @!%p9 bra red64_end;
    add.s32 %r20, %r2, 64;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
red64_end:
    bar.sync 0;

    setp.lt.s32 %p9, %r2, 32;
    @!%p9 bra red32_end;
    add.s32 %r20, %r2, 32;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
red32_end:
    bar.sync 0;

    setp.lt.s32 %p9, %r2, 16;
    @!%p9 bra red16_end;
    add.s32 %r20, %r2, 16;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
red16_end:
    bar.sync 0;

    setp.lt.s32 %p9, %r2, 8;
    @!%p9 bra red8_end;
    add.s32 %r20, %r2, 8;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
red8_end:
    bar.sync 0;

    setp.lt.s32 %p9, %r2, 4;
    @!%p9 bra red4_end;
    add.s32 %r20, %r2, 4;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
red4_end:
    bar.sync 0;

    setp.lt.s32 %p9, %r2, 2;
    @!%p9 bra red2_end;
    add.s32 %r20, %r2, 2;
    mul.wide.s32 %rd20, %r20, 8;
    add.s64 %rd21, %rd10, %rd20;
    add.s64 %rd22, %rd11, %rd20;
    ld.shared.f64 %fd20, [%rd21];
    ld.shared.f64 %fd21, [%rd22];
    ld.shared.f64 %fd22, [%rd13];
    ld.shared.f64 %fd23, [%rd14];
    add.f64 %fd22, %fd22, %fd20;
    add.f64 %fd23, %fd23, %fd21;
    st.shared.f64 [%rd13], %fd22;
    st.shared.f64 [%rd14], %fd23;
