    div.rn.f64 %fd27, %fd24, %fd26;
    mul.f64 %fd28, %fd27, %fd27;
    div.rn.f64 %fd29, %fd25, %fd26;
    sub.f64 %fd30, %fd29, %fd28;
    cvt.f64.f32 %fd31, %f1;
    add.f64 %fd32, %fd30, %fd31;
    sqrt.rn.f64 %fd33, %fd32;
    mov.f64 %fd34, 0d3FF0000000000000;
    div.rn.f64 %fd35, %fd34, %fd33;

