    add.s64 %rd28, %rd6, %rd27;
    ld.global.v4.f32 {%f2, %f3, %f4, %f5}, [%rd28];
    cvt.f64.f32 %fd38, %f2;
    sub.f64 %fd39, %fd38, %fd36;
    mul.f64 %fd40, %fd39, %fd37;
    cvt.rn.f32.f64 %f2, %fd40;
    cvt.f64.f32 %fd38, %f3;
    sub.f64 %fd39, %fd38, %fd36;
    mul.f64 %fd40, %fd39, %fd37;
    cvt.rn.f32.f64 %f3, %fd40;
    cvt.f64.f32 %fd38, %f4;
    sub.f64 %fd39, %fd38, %fd36;
    mul.f64 %fd40, %fd39, %fd37;
    cvt.rn.f32.f64 %f4, %fd40;
    cvt.f64.f32 %fd38, %f5;
    sub.f64 %fd39, %fd38, %fd36;
    mul.f64 %fd40, %fd39, %fd37;
    cvt.rn.f32.f64 %f5, %fd40;
    add.s64 %rd29, %rd3, %rd27;
    ld.global.v4.f32 {%f10, %f11, %f12, %f13}, [%rd29];
    add.s64 %rd30, %rd4, %rd27;
    ld.global.v4.f32 {%f14, %f15, %f16, %f17}, [%rd30];
    fma.rn.f32 %f20, %f2, %f10, %f14;
    fma.rn.f32 %f21, %f3, %f11, %f15;
    fma.rn.f32 %f22, %f4, %f12, %f16;
    fma.rn.f32 %f23, %f5, %f13, %f17;
    add.s64 %rd31, %rd7, %rd27;
    st.global.v4.f32 [%rd31], {%f20, %f21, %f22, %f23};

    add.s32 %r6, %r6, %r7;
    bra loop2;

loop2_end:
    ret;
