"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layer_norm_kernel")

class ModelNew(nn.Module):
    def __init__(self, normalized_shape):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N = 1
        for d in self.normalized_shape:
            N *= d
        batch = x.numel() // N

        out = torch.empty_like(x)

        module = _get_ptx_module()
        module.launch(
            "layer_norm_kernel",
            grid=(batch, 1, 1),
            block=(1024, 1, 1),
            arguments=[x, out, self.weight, self.bias, i32(N), f32(self.eps)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

