        module.launch(
            "layer_norm_kernel",
            grid=(batch, 1, 1),
            block=(256, 1, 1),
            arguments=[x, out, self.weight, self.bias, i32(N), f32(self.eps)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
